 var original=d.CaptureDungeonSave();var clean=DungeonMapPersistence.Copy(original);clean.enemies.Clear();clean.triggeredEncounters=new string[0];clean.interactions.completedEvents.RemoveAll(e=>e.StartsWith("dungeon.entry.notice.v1:")||e.StartsWith("retro.pipe."));d.RestoreDungeonSave(clean);composer.Build();yield return null;yield return null;bushes=composer.GetComponentsInChildren<RetroDungeonBush>();Set("directorNextSpawnTime",Time.unscaledTime+1000);d.StartCoroutine((IEnumerator)Call("ShowDungeonEntryNotice"));yield return null;Check(W.Active&&W.Current.speaker=="GUÍA","Guide speaks on first arrival");W.CompleteLetters();yield return Capture("Guide");yield return Finish();string notice="dungeon.entry.notice.v1:"+d.mapSettings.mapId;Check(d.CaptureDungeonSave().interactions.completedEvents.Contains(notice),"Guide notice saved in existing map events");
