 var bush=Array.Find(bushes,b=>b.persistentId=="retro.pipe.front.north");Warp(5,10);yield return new WaitForSecondsRealtime(1);Check(bush.Armed&&bush.SuccessfulSpawns==0,"Bush shakes before an enemy appears");var rest=bush.foliage.localPosition;yield return new WaitForSecondsRealtime(.08f);Check(Vector3.Distance(rest,bush.foliage.localPosition)>.0001f,"Warning visibly shakes foliage");yield return (IEnumerator)Call("Move",1,0);yield return new WaitForSecondsRealtime(.08f);Check(bush.SuccessfulSpawns==1,"Walking after warning triggers one emergence");Check(bush.Animating,"Enemy uses a jump animation");yield return Capture("BushJump");yield return new WaitForSecondsRealtime(.9f);Check(d.RetroPipeAttempts(bush.persistentId)==1,"Existing emitter persistence ID retained");int count=d.CaptureEnemyProgression().Count;Check(!bush.TryActivate()&&d.CaptureEnemyProgression().Count==count,"No duplicate spawn from consumed bush");
 var save=d.CaptureDungeonSave();Warp(5,11);yield return (IEnumerator)Call("Move",1,0);yield return new WaitForSecondsRealtime(1.3f);Check(d.LaboratoryBattle,"Bush enemy enters normal combat");var stage=(GameObject)Get("battleStage");Check(stage!=null&&stage.transform.Find("Battle floor").GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap")==settings.floor,"Combat uses updated Pixel floor");Check(stage!=null&&!stage.GetComponentsInChildren<Transform>().Any(t=>t.name=="Battle decorative pipe"),"Combat backdrop has no pipes");yield return Capture("PixelBattle");d.RestoreDungeonSave(save);if(stage!=null)stage.SetActive(false);string previous=DungeonSaveStore.editorTestPath;DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/PixelBushPortalsSave.json");DungeonSaveStore.Write(save,0,"Bush fixture");var loaded=DungeonSaveStore.Read(0);d.RestoreDungeonSave(loaded);DungeonSaveStore.editorTestPath=previous;Check(d.RetroPipeAttempts(bush.persistentId)==1&&!bush.TryActivate(),"Save and load preserve consumed emitter");yield return (IEnumerator)Call("ShowDungeonEntryNotice");Check(!W.Active,"Completed guide notice does not repeat after load");
